/**
 * 세계 지도 컴포넌트 - OpenLayers 기반 인터랙티브 유럽 지도
 *
 * 기능:
 * - ArcGIS NatGeo 타일 레이어로 실제 유럽 지도 표시
 * - 각 지역(REGIONS)을 원형 마커로 표시 (수도 이름 라벨 포함)
 * - 마커 클릭 → onRegionSelect 콜백 → RegionInfoModal 표시
 * - 잠금/해제 상태에 따라 마커 색상 변경 (해제: 지역 고유색, 잠금: 회색)
 * - 현재 위치한 지역은 더 큰 마커 + 금색 테두리로 강조
 * - 호버 시 커서 변경 (해제된 지역만 pointer)
 *
 * OpenLayers 설정:
 * - 좌표계: EPSG:3857 (Web Mercator)
 * - 중심: 유럽 중앙 [경도 10, 위도 45]
 * - 줌 범위: 3~7 (유럽 전체 ~ 국가 수준)
 * - 범위 제한: 서경 20° ~ 동경 80°, 남위 10° ~ 북위 62° (유럽 영역)
 *
 * 하단 우측: 몬스터 속성 상성 안내 (LAND > SEA > SKY > LAND)
 */

import { useEffect, useRef } from 'react';

/* ── OpenLayers 임포트 ── */
import OlMap from 'ol/Map';                              // 지도 메인 객체
import View from 'ol/View';                              // 카메라/뷰포트 설정
import TileLayer from 'ol/layer/Tile';                   // 래스터 타일 레이어
import VectorLayer from 'ol/layer/Vector';               // 벡터(마커) 레이어
import VectorSource from 'ol/source/Vector';             // 벡터 데이터 소스
import XYZ from 'ol/source/XYZ';                         // XYZ 타일 소스 (ArcGIS)
import Feature from 'ol/Feature';                        // 지도 위 개별 객체 (마커)
import Point from 'ol/geom/Point';                       // 점 지오메트리
import { fromLonLat, transformExtent } from 'ol/proj';   // 좌표 변환 (WGS84 → Web Mercator)
import { Circle as CircleStyle, Fill, Stroke, Style, Text } from 'ol/style';  // 스타일링
import { defaults as defaultControls } from 'ol/control'; // 기본 컨트롤 (줌 등)
import 'ol/ol.css';                                       // OpenLayers 기본 CSS

import { REGIONS } from '../constants/regions';           // 지역 데이터 (좌표, 색상, 언락 레벨 등)
import { MONSTER_TYPES } from '../constants/config';      // 몬스터 속성 타입 (상성 안내용)

/** Props 인터페이스 */
interface WorldMapProps {
  onRegionSelect: (regionId: string) => void;  // 지역 마커 클릭 시 콜백 (지역 ID 전달)
  unlockedRegions: string[];                   // 해금된 지역 ID 배열
  currentRegion: string;                       // 현재 위치한 지역 ID (마커 강조용)
  playerLevel: number;                         // 플레이어 레벨 (레벨 기반 해금 판단용)
}

export default function WorldMap({ onRegionSelect, unlockedRegions, currentRegion, playerLevel }: WorldMapProps) {
  /** 지도 DOM 컨테이너 ref */
  const mapRef = useRef<HTMLDivElement>(null);
  /** OpenLayers Map 인스턴스 ref (재생성 방지) */
  const mapInstanceRef = useRef<OlMap | null>(null);

  /**
   * 첫 번째 useEffect: 지도 초기화 (마운트 시 1회)
   * - 타일 레이어 + 벡터 레이어(마커) 생성
   * - 클릭/호버 이벤트 등록
   * - cleanup 시 지도 인스턴스 해제
   */
  useEffect(() => {
    // 이미 생성되었거나 DOM이 없으면 스킵
    if (!mapRef.current || mapInstanceRef.current) return;

    /** 유럽 중심 좌표 (경도 10°, 위도 45°) → Web Mercator로 변환 */
    const europeCenter = fromLonLat([10, 45]);

    /** 배경 타일 레이어: ArcGIS NatGeo 세계 지도 */
    const tileLayer = new TileLayer({
      source: new XYZ({
        url: 'https://server.arcgisonline.com/ArcGIS/rest/services/NatGeo_World_Map/MapServer/tile/{z}/{y}/{x}',
        attributions: 'Tiles \u00A9 Esri'
      })
    });

    /** 지역 마커 Feature 생성 */
    const markers: Feature[] = [];
    Object.entries(REGIONS).forEach(([id, region]) => {
      /** 해금 여부: 직접 해금 목록에 있거나, 플레이어 레벨이 요구 레벨 이상 */
      const isUnlocked = unlockedRegions.includes(id) || region.unlockLevel <= playerLevel;

      /** Feature 생성: 좌표를 WGS84 → Web Mercator로 변환 */
      const feature = new Feature({
        geometry: new Point(fromLonLat(region.coordinates)),
        regionId: id,            // 커스텀 속성: 지역 ID
        name: region.name,       // 커스텀 속성: 지역 이름
        unlocked: isUnlocked,    // 커스텀 속성: 해금 여부
      });

      /** 마커 스타일 설정 */
      feature.setStyle(new Style({
        image: new CircleStyle({
          radius: currentRegion === id ? 18 : 14,  // 현재 지역은 더 큰 마커
          fill: new Fill({ color: isUnlocked ? region.color : '#666666' }),  // 해금: 고유색, 잠금: 회색
          stroke: new Stroke({
            color: currentRegion === id ? '#FFD700' : (isUnlocked ? '#ffffff' : '#333333'),  // 현재 지역: 금색 테두리
            width: currentRegion === id ? 4 : 2
          }),
        }),
        text: new Text({
          text: region.capital,                      // 수도 이름 라벨
          font: 'bold 12px Arial',
          fill: new Fill({ color: '#ffffff' }),
          stroke: new Stroke({ color: '#000000', width: 3 }),  // 검은 외곽선 (가독성)
          offsetY: -25,                              // 마커 위에 표시
        }),
      }));

      markers.push(feature);
    });

    /** 벡터 레이어: 모든 마커를 담는 레이어 */
    const vectorLayer = new VectorLayer({
      source: new VectorSource({ features: markers }),
    });

    /** OpenLayers Map 인스턴스 생성 */
    const map = new OlMap({
      target: mapRef.current,                          // DOM 컨테이너
      layers: [tileLayer, vectorLayer],                // 타일 + 벡터 레이어
      view: new View({
        center: europeCenter,                          // 초기 중심 좌표
        zoom: 4.5,                                     // 초기 줌 레벨
        minZoom: 3,                                    // 최소 줌 (넓은 뷰)
        maxZoom: 7,                                    // 최대 줌 (국가 수준)
        extent: transformExtent([-32, 10, 80, 62], 'EPSG:4326', 'EPSG:3857'),  // 이동 범위 (유럽 + 아즈텍 항구)
      }),
      controls: defaultControls({ zoom: true, rotate: false, attribution: false }),  // 줌만 활성화
    });

    /**
     * 클릭 이벤트: 마커 위 클릭 시 지역 선택
     * - forEachFeatureAtPixel: 클릭 위치에 있는 Feature 탐색
     * - 해금된 지역만 선택 가능
     */
    map.on('click', (evt) => {
      map.forEachFeatureAtPixel(evt.pixel, (feature) => {
        const regionId = (feature as Feature).get('regionId');
        const isUnlocked = (feature as Feature).get('unlocked');
        if (regionId && isUnlocked) {
          onRegionSelect(regionId);  // 부모 컴포넌트로 선택된 지역 ID 전달
        }
      });
    });

    /**
     * 호버 이벤트: 해금된 마커 위에서 커서를 pointer로 변경
     */
    map.on('pointermove', (evt) => {
      const hit = map.forEachFeatureAtPixel(evt.pixel, (feature) => (feature as Feature).get('unlocked'));
      map.getTargetElement().style.cursor = hit ? 'pointer' : '';
    });

    mapInstanceRef.current = map;

    /** cleanup: 컴포넌트 언마운트 시 지도 해제 */
    return () => {
      if (mapInstanceRef.current) {
        mapInstanceRef.current.setTarget(undefined);  // DOM 연결 해제
        mapInstanceRef.current = null;
      }
    };
    // 지도 인스턴스는 마운트 시 1회만 생성. unlockedRegions/currentRegion/playerLevel/onRegionSelect
    // 변화는 아래 두 번째 useEffect에서 스타일을 갱신하는 방식으로 처리한다.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  /**
   * 두 번째 useEffect: 마커 스타일 동적 업데이트
   * - unlockedRegions, currentRegion, playerLevel 변경 시 마커 재스타일링
   * - 지도를 재생성하지 않고 벡터 레이어의 Feature 스타일만 갱신
   */
  useEffect(() => {
    if (!mapInstanceRef.current) return;

    /** 벡터 레이어 참조 (layers[1]) */
    const vectorLayer = mapInstanceRef.current.getLayers().getArray()[1] as VectorLayer<VectorSource>;
    if (!vectorLayer) return;

    /** 모든 마커의 스타일을 현재 상태에 맞게 재설정 */
    vectorLayer.getSource()?.getFeatures().forEach(feature => {
      const regionId = feature.get('regionId');
      const region = REGIONS[regionId];
      const isUnlocked = unlockedRegions.includes(regionId) || region.unlockLevel <= playerLevel;

      feature.set('unlocked', isUnlocked);  // 해금 상태 업데이트
      feature.setStyle(new Style({
        image: new CircleStyle({
          radius: currentRegion === regionId ? 18 : 14,
          fill: new Fill({ color: isUnlocked ? region.color : '#666666' }),
          stroke: new Stroke({
            color: currentRegion === regionId ? '#FFD700' : (isUnlocked ? '#ffffff' : '#333333'),
            width: currentRegion === regionId ? 4 : 2
          }),
        }),
        text: new Text({
          text: region.capital,
          font: 'bold 12px Arial',
          fill: new Fill({ color: '#ffffff' }),
          stroke: new Stroke({ color: '#000000', width: 3 }),
          offsetY: -25,
        }),
      }));
    });
  }, [unlockedRegions, currentRegion, playerLevel]);  // 이 값들이 바뀔 때마다 재실행

  return (
    <div className="relative w-full h-full">
      {/* OpenLayers 지도가 렌더링될 DOM 컨테이너 */}
      <div ref={mapRef} className="w-full h-full rounded-lg" />

      {/* 좌상단: 게임 타이틀 + 안내 */}
      <div className="absolute top-2 left-2 bg-black/80 p-3 rounded-lg text-white text-sm">
        <h3 className="font-bold text-yellow-400 mb-2">{'\uD83E\uDDED'} Broken Compass</h3>
        <p className="text-xs text-gray-300">도시를 클릭하여 탐험하세요</p>
      </div>

      {/* 우하단: 몬스터 속성 상성 안내 (LAND > SEA > SKY > LAND 삼각 관계) */}
      <div className="absolute bottom-2 right-2 bg-black/80 p-3 rounded-lg text-white text-xs">
        <div className="font-bold mb-2">몬스터 속성</div>
        {/* 속성 아이콘 + 이름 목록 */}
        <div className="flex gap-3">
          {Object.entries(MONSTER_TYPES).map(([key, type]) => (
            <div key={key} className="flex items-center gap-1">
              <span>{type.icon}</span>
              <span style={{ color: type.color }}>{type.name}</span>
            </div>
          ))}
        </div>
        {/* 상성 관계 설명 */}
        <div className="mt-2 text-gray-400">{'\uD83C\uDF0D'}{'\u2192'}{'\u2601\uFE0F'} 강함 | {'\uD83C\uDF0A'}{'\u2192'}{'\uD83C\uDF0D'} 강함 | {'\u2601\uFE0F'}{'\u2192'}{'\uD83C\uDF0A'} 강함</div>
      </div>
    </div>
  );
}
